export { createMmkvStorage, mmkvStorage } from './mmkvStorage';
export type { PersistStorage } from './mmkvStorage';
import { createMMKV, type MMKV } from 'react-native-mmkv';

export type PersistStorage = {
  getItem: (key: string) => Promise<string | null>;
  setItem: (key: string, value: string) => Promise<void>;
  removeItem: (key: string) => Promise<void>;
};

export const createMmkvStorage = (mmkv: MMKV): PersistStorage => ({
  getItem: key => Promise.resolve(mmkv.getString(key) ?? null),
  setItem: (key, value) => {
    mmkv.set(key, value);
    return Promise.resolve();
  },
  removeItem: key => {
    mmkv.remove(key);
    return Promise.resolve();
  },
});

export const mmkvStorage = createMmkvStorage(createMMKV({ id: 'app-state' }));
import { createMMKV } from 'react-native-mmkv';
import { createAppStore } from '@app/store';
import {
  postLoaded,
  postsLoaded,
  selectSortedPosts,
  toggleFavorite,
} from '@entities/post';
import { createMmkvStorage } from '@shared/storage';
import { makePost } from '../../__fixtures__/post';

const rehydrate = (storage: ReturnType<typeof createMmkvStorage>) => {
  const app = createAppStore(storage);
  return new Promise<typeof app>(resolve => {
    const unsubscribe = app.persistor.subscribe(() => {
      if (app.persistor.getState().bootstrapped) {
        unsubscribe();
        resolve(app);
      }
    });
  });
};

describe('persistence', () => {
  it('restores written state in a fresh store', async () => {
    const storage = createMmkvStorage(createMMKV({ id: 'persistence-test' }));

    const first = await rehydrate(storage);
    first.store.dispatch(postsLoaded([makePost(2), makePost(1)]));
    first.store.dispatch(postLoaded(makePost(3)));
    first.store.dispatch(toggleFavorite(2));
    await first.persistor.flush();

    const second = await rehydrate(storage);
    const state = second.store.getState();

    expect(state.favorites).toEqual([2]);
    expect(state.posts.listRequested).toBe(true);
    expect(state.posts.detailRequestedIds).toEqual([3]);
    expect(selectSortedPosts(state).map(post => post.id)).toEqual([2, 1, 3]);
  });
});
import {
  favoritesReducer,
  postLoaded,
  postsLoaded,
  postsReducer,
  toggleFavorite,
} from '@entities/post';
import { makePost } from '../../__fixtures__/post';

describe('favoritesReducer', () => {
  it('adds and removes an id', () => {
    const added = favoritesReducer([], toggleFavorite(2));
    expect(added).toEqual([2]);
    expect(favoritesReducer(added, toggleFavorite(2))).toEqual([]);
  });

  it('returns to the initial state after two toggles of any id', () => {
    const initial = [1, 3, 5];
    [1, 2, 3, 6].forEach(id => {
      const twice = favoritesReducer(
        favoritesReducer(initial, toggleFavorite(id)),
        toggleFavorite(id),
      );
      expect(twice).toEqual(initial);
    });
  });
});

describe('postsReducer', () => {
  const initial = postsReducer(undefined, { type: '@@init' });

  it('starts with nothing requested', () => {
    expect(initial).toEqual({
      ids: [],
      entities: {},
      listRequested: false,
      detailRequestedIds: [],
    });
  });

  it('normalizes the list by id and marks it requested', () => {
    const state = postsReducer(
      initial,
      postsLoaded([makePost(2), makePost(1)]),
    );
    expect(state.ids).toEqual([2, 1]);
    expect(state.entities[1]).toEqual(makePost(1));
    expect(state.listRequested).toBe(true);
  });

  it('records a loaded detail once', () => {
    const once = postsReducer(initial, postLoaded(makePost(4)));
    const twice = postsReducer(once, postLoaded(makePost(4)));
    expect(twice.detailRequestedIds).toEqual([4]);
    expect(twice.ids).toEqual([4]);
    expect(twice.listRequested).toBe(false);
  });
});
